// swift-tools-version:5.9
//
// Distribution package for AgentforceSDK — generated by
// scripts/build-xcframework.sh. Wrapper-pattern: the public library
// product is implemented by AgentforceSDKTarget, which carries the
// binary XCFramework plus its SPM-resolved transitive dependencies.

import PackageDescription

let package = Package(
    name: "AgentforceSDK",
    defaultLocalization: "en",
    platforms: [
        .iOS(.v17)
    ],
    products: [
        .library(
            name: "AgentforceSDK",
            targets: ["AgentforceSDKTarget"]
        )
    ],
    // Keep in sync with ../../Package.swift — see
    // docs/spm-binary-distribution.md "Dependency-list alignment".
    //
    // swift-markdown-ui is intentionally NOT listed: AgentforceSDK
    // imports it as @_implementationOnly so MarkdownUI types do not
    // appear in AgentforceSDK's .swiftinterface. Statically-linked
    // MarkdownUI symbols are baked into AgentforceSDK.framework
    // already; declaring it here would cause SwiftPM to also build
    // MarkdownUI.framework on the consumer side, creating two copies
    // of the Swift classes at runtime (ObjC duplicate-class warnings).
    dependencies: [
        .package(url: "https://github.com/forcedotcom/SalesforceMobileInterfaces-iOS", from: "1.0.0"),
        .package(url: "https://github.com/Salesforce-Async-Messaging/SMIClientCore-iOS.swift.git", from: "1.11.0"),
        .package(url: "https://github.com/salesforce/SharedUI-iOS", .upToNextMajor(from: "1.3.1")),
    ],
    targets: [
        .binaryTarget(
            name: "AgentforceSDK",
            // Adjacent to this Package.swift when distributed locally.
            // For a hosted release, replace with:
            //   url: "https://<host>/AgentforceSDK-<version>.xcframework.zip",
            //   checksum: "<output of swift package compute-checksum>"
            url: "https://github.com/salesforce/AgentforceMobileSDK-iOS/releases/download/18.26.9-rc2/AgentforceMobileSDK-262-1-3-RC2-spm.xcframework.zip",
            checksum: "3db81d374a4da701a6068a9639a3003acd128ec47d1ee8858e2b0f95fd514a6d"
        ),
        .binaryTarget(
            name: "AgentforceService",
            // Adjacent to this Package.swift when distributed locally —
            // build-xcframework.sh copies AgentforceService.xcframework
            // into ../ next to AgentforceSDK.xcframework. The source is
            // controlled by the AGENTFORCE_SERVICE_XCFRAMEWORK env var
            // (default: ../AgentforceService/build/... — i.e. a sibling
            // clone of the AgentforceService repo next to this one).
            // For a hosted release, replace with:
            //   url: "https://<host>/AgentforceService-<version>.xcframework.zip",
            //   checksum: "<output of swift package compute-checksum>"
            // See docs/spm-binary-distribution.md "Binary-on-binary
            // requirement" for why source resolution does not work.
            url: "https://github.com/forcedotcom/AgentforceMobileService-iOS/releases/download/6.11.3-rc1/AgentforceMobileService-262-1-3-RC-spm.xcframework.zip",
            checksum: "7dec39d7a1c04dab73ab63aa50dd96d5314376dd96408fbc71d41be8a3fc7cd4"
        ),
        .target(
            name: "AgentforceSDKTarget",
            dependencies: [
                "AgentforceSDK",
                "AgentforceService",
                // No "MarkdownUI" — see comment on `dependencies:` above.
                // The wrapper target must declare every module that the
                // binary .swiftinterface files import — even for modules
                // that AgentforceService re-exports via @_exported. The
                // re-export flattens symbols for the consumer's source,
                // but the build system still needs each .swiftmodule on
                // the import path to verify the binary interfaces.
                // Mirror the dep list of AgentforceService's own dist
                // Package.swift (Logging/Navigation/Network/User +
                // SMIClientCore, which bundles SMIMultimediaCommon).
                .product(name: "SalesforceLogging",    package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceNavigation", package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceNetwork",    package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceUser",       package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SMIClientCore",        package: "SMIClientCore-iOS.swift"),
                .product(name: "SharedUI", package: "SharedUI-iOS"),
            ],
            path: "Sources/AgentforceSDKTarget"
        )
    ]
)
